css:
/* Линия прогресса по шагам. Отрезок между точками заполняется через transform: scaleY, привязанный к прокрутке.
   Без поддержки CSS-шкал ведёт запасной JS; без JS линия и точки стоят заполненными. */
.spl {
  --spl-dot: 20px;                               /* размер точки */
  --spl-top: 4px;                                /* сдвиг точки от верха шага: выровняйте по первой строке заголовка */
  --spl-gap: 40px;                               /* расстояние между шагами */
  --spl-line: 2px;
  --spl-color: var(--primary, #2446d8);          /* заливка и точка: контраст с фоном от 3:1 */
  --spl-track: var(--border, #d9dce3);           /* незаполненная линия */
  --spl-read: 60%;                               /* линия чтения от верха экрана; запасной JS читает это же число */
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: var(--spl-gap);
}
.spl-title { margin: 0 0 32px; font-size: clamp(28px, 3.4vw, 44px); line-height: 1.15; }
.spl__step { position: relative; padding-left: calc(var(--spl-dot) + 20px); }
.spl__h { margin: 0 0 6px; font-size: clamp(20px, 2vw, 24px); line-height: 1.25; }
.spl__step p { margin: 0; max-width: 48ch; color: var(--text-muted, #555b66); }
.spl__dot {
  position: absolute; left: 0; top: var(--spl-top); z-index: 1;
  width: var(--spl-dot); height: var(--spl-dot); box-sizing: border-box;
  border-radius: 50%;
  border: 2px solid var(--spl-color);
  background: var(--background, #ffffff);
}
.spl__dot::after {                               /* заливка точки: загорается, когда до неё дошла линия */
  content: ""; position: absolute; inset: 3px; border-radius: 50%;
  background: var(--spl-color);
  transition: transform 240ms cubic-bezier(.2, 0, 0, 1), opacity 240ms cubic-bezier(.2, 0, 0, 1);
}
.spl.is-live .spl__step:not(.is-on) .spl__dot::after { transform: scale(.4); opacity: 0; transition-duration: 160ms; }
/* Отрезок от низа своей точки до верха следующей. Шкала прокрутки — на нём: «линия чтения» = зазор нулевой высоты на --spl-read */
.spl__seg {
  position: absolute;
  left: calc(var(--spl-dot) / 2 - var(--spl-line) / 2);
  top: calc(var(--spl-top) + var(--spl-dot));
  bottom: calc(-1 * (var(--spl-gap) + var(--spl-top)));
  width: var(--spl-line);
  background: var(--spl-track);
  view-timeline: --spl-seg block;
  view-timeline-inset: var(--spl-read) calc(100% - var(--spl-read));
}
.spl__fill { display: block; height: 100%; background: var(--spl-color); transform-origin: 50% 0; }
@keyframes spl-fill { from { transform: scaleY(0); } to { transform: scaleY(1); } }
@media (prefers-reduced-motion: no-preference) {
  @supports (animation-timeline: view()) {
    .spl__fill {
      animation: spl-fill 1ms linear both;        /* 1ms нужен Firefox; на шкале прокрутки время пересчитывается в долю пути */
      animation-timeline: --spl-seg;              /* строго ПОСЛЕ animation */
      animation-range: cover 0% cover 100%;       /* от «верх отрезка на линии чтения» до «низ отрезка на линии чтения» */
    }
    .spl.spl-js .spl__fill { animation: none; }  /* шкала замерла — ведёт JS */
  }
}
/* Уровень 1 (убрать): линия заполнена целиком, все точки горят, ничего не движется */
@media (prefers-reduced-motion: reduce) {
  .spl__fill { animation: none !important; transform: none !important; }
  .spl.is-live .spl__step:not(.is-on) .spl__dot::after { transform: none; opacity: 1; transition: none; }
}

js:
// Точки шагов (везде) и запасной путь для линии (Firefox или замершая CSS-шкала). Без зависимостей.
(() => {
  document.querySelectorAll('[data-spl]').forEach((list) => {
    if (!('IntersectionObserver' in window)) return; // без IO линия и точки стоят заполненными
    const read = parseFloat(getComputedStyle(list).getPropertyValue('--spl-read')) || 60; // линия чтения, % экрана
    // Точка горит, когда её верх выше линии чтения — и когда она уже ушла за верх экрана
    const io = new IntersectionObserver((es) => es.forEach((e) => {
      e.target.parentElement.classList.toggle('is-on', e.boundingClientRect.top < e.rootBounds.bottom);
    }), { rootMargin: `0px 0px -${100 - read}% 0px` });
    const y0 = innerHeight * read / 100; // начальное состояние — сразу, без мигания точек при загрузке
    list.querySelectorAll('.spl__dot').forEach((d) => { d.parentElement.classList.toggle('is-on', d.getBoundingClientRect().top < y0); io.observe(d); });
    list.classList.add('is-live');
    // Линия: CSS-шкала есть и не замерла (html, body { overflow-x: hidden } делает body контейнером прокрутки) — JS не нужен
    const fill = list.querySelector('.spl__fill');
    const src = fill?.getAnimations()[0]?.timeline?.source;
    const cssOk = window.CSS && CSS.supports('animation-timeline', 'view()');
    if (!fill || (cssOk && !(src && src !== document.scrollingElement && src.scrollHeight <= src.clientHeight))) return;
    list.classList.add('spl-js');
    const segs = [...list.querySelectorAll('.spl__seg')];
    let raf = 0, on = false;
    const frame = () => {
      raf = 0;
      const y = innerHeight * read / 100;
      const p = segs.map((s) => { const r = s.getBoundingClientRect(); return Math.min(1, Math.max(0, (y - r.top) / r.height)); }); // сначала чтения
      segs.forEach((s, i) => { s.firstElementChild.style.transform = `scaleY(${p[i].toFixed(4)})`; }); // потом записи
    };
    const tick = () => { if (!raf) raf = requestAnimationFrame(frame); };
    // На прокрутку подписываемся, только пока список рядом с экраном
    new IntersectionObserver((es) => {
      const vis = es[es.length - 1].isIntersecting;
      if (vis === on) return;
      on = vis;
      if (on) { addEventListener('scroll', tick, { passive: true, capture: true }); addEventListener('resize', tick); tick(); }
      else { removeEventListener('scroll', tick, { capture: true }); removeEventListener('resize', tick); tick(); }
    }, { rootMargin: '50% 0px' }).observe(list);
  });
})();

