// Только если GSAP уже есть в проекте: npm i gsap (Standard License, не MIT), без CDN. Разметка и CSS те же, JS рецепта не подключать.
// Класс spl-js снимает CSS-анимацию линии, is-live включает гаснущие точки — оба правила уже есть в CSS.
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
gsap.registerPlugin(ScrollTrigger);

const list = document.querySelector('[data-spl]');
const mm = gsap.matchMedia();
mm.add({ motion: '(prefers-reduced-motion: no-preference)', reduce: '(prefers-reduced-motion: reduce)' }, ({ conditions }) => {
  if (conditions.reduce) return; // линия заполнена, точки горят — это делает CSS
  list.classList.add('spl-js', 'is-live');
  gsap.utils.toArray('.spl__seg', list).forEach((seg) => gsap.fromTo(seg.firstElementChild, { scaleY: 0 }, {
    scaleY: 1, ease: 'none', // в scrub только без кривой
    scrollTrigger: { trigger: seg, start: 'top 60%', end: 'bottom 60%', scrub: true }, // линия чтения — 60 % экрана
  }));
  gsap.utils.toArray('.spl__dot', list).forEach((dot) => ScrollTrigger.create({
    trigger: dot, start: 'top 60%', end: 'max', // горит от линии чтения и до конца страницы
    onToggle: (self) => dot.parentElement.classList.toggle('is-on', self.isActive),
  }));
  return () => list.classList.remove('spl-js', 'is-live');
});
